int calculate(int x, int y) { return x * y; }

// Function Pointer Declaration and Assignment
// Stores memory address (8 bytes on 64-bit systems)
int (*p_func)(int, int) = &calculate;

// Function Reference Declaration and Initialization
// Acts as an alias; cannot be reseated
int (&r_func)(int, int) = calculate;

// Invocation via pointer (implicit dereference)
int result_ptr = p_func(5, 5);

// Invocation via reference (direct call syntax)
int result_ref = r_func(6, 6);
